import re, subprocess, sys
sys.path.insert(0, '/home/ubuntu/hh2_masters')
SRC = '/home/ubuntu/hh2_masters'
def run(cmd):
    return subprocess.run(cmd, capture_output=True, text=True, stdin=subprocess.DEVNULL)
def segments(name, noise, d):
    src = f'{SRC}/{name}.wav'
    r = run(['ffmpeg', '-nostdin', '-i', src, '-af', f'silencedetect=noise={noise}dB:d={d}', '-f', 'null', '-'])
    starts = [float(x) for x in re.findall(r'silence_start: ([\d.]+)', r.stderr)]
    ends = [float(x) for x in re.findall(r'silence_end: ([\d.]+)', r.stderr)]
    total = float(run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', src]).stdout)
    segs, cursor = [], 0.0
    for s, e in zip(starts, ends + [total] * (len(starts) - len(ends))):
        if s - cursor > 0.2:
            segs.append((round(cursor, 2), round(s, 2)))
        cursor = e
    if total - cursor > 0.2:
        segs.append((round(cursor, 2), round(total, 2)))
    return segs
for name in ['vo_blaze', 'vo_frost', 'vo_psi']:
    for noise, d in [(-35, 0.4), (-30, 0.35), (-25, 0.3)]:
        segs = segments(name, noise, d)
        print(name, noise, d, len(segs), segs)

